mapper.select:
select p.id as paymentId, p.order_id as orderId, method_code.code as paymentMethodCode, payStatus_code.code as paymentStatus from payment p
join common_code method_code on method_code.id = p.method_id join common_code payStatus_code on payStatus_code.id = p.status_id
where p.idempotency_key = #{idempotencyKey}
